def availability(statuses):
    if not statuses: return None
    return sum(s < 500 for s in statuses) / len(statuses)

def deduplicate(events):
    seen = set()
    result = []
    for event in events:
        if event['id'] not in seen:
            seen.add(event['id'])
            result.append(event)
    return result

def failed_deployments(events):
    seen, counts = set(), {}
    for event in events:
        if event["id"] in seen:
            continue
        seen.add(event["id"])
        if event["status"] == "failed":
            team = event["team"]
            counts[team] = counts.get(team, 0) + 1
    return counts

