def triage(incidents, k):
    if k <= 0:
        return []
    ranked = sorted(incidents, key=lambda x: (x["severity"], x["opened"], x["id"]))
    return [x["id"] for x in ranked[:k]]

def request_with_retry(send, attempts):
    if attempts < 1:
        raise ValueError("attempts must be positive")
    for index in range(attempts):
        status = send()
        if not (status == 429 or 500 <= status <= 599) or index == attempts - 1:
            return status

def replay(events):
    seen, services = set(), {}
    for event in events:
        if event["id"] in seen:
            continue
        seen.add(event["id"])
        services[event["service"]] = event["version"]
    return services

tests:
